func valueEquipmentType(p unsafe.Pointer, c int32) any {
	r := (*equipmenttype.EquipmentType)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.Status)
	case 4:
		return r.Code
	case 5:
		if r.Description == "" {
			return nil
		}
		return r.Description
	case 6:
		return string(r.Class)
	case 7:
		if r.Color == "" {
			return nil
		}
		return r.Color
	case 8:
		if r.InteriorLength == nil {
			return nil
		}
		return *r.InteriorLength
	case 9:
		if r.DeckType == "" {
			return nil
		}
		return string(r.DeckType)
	case 10:
		if r.DeckHeightInches == nil {
			return nil
		}
		return *r.DeckHeightInches
	case 11:
		if r.WellLengthFeet == nil {
			return nil
		}
		return *r.WellLengthFeet
	case 12:
		if r.AxleCount == nil {
			return nil
		}
		return *r.AxleCount
	case 13:
		return r.SearchVector
	case 14:
		return r.Rank
	case 15:
		return r.Version
	case 16:
		return r.CreatedAt
	case 17:
		return r.UpdatedAt
	}
	return nil
}

